dex)	-- 失败，活动已经结束	if not Sys_ChkFullTime(tActivityTime["RamadanActivity"]["ActivityTime"]) then		LinkNpcGossipFunc_New(nNpcId,"1-2")		return false	end		-- 失败，等级判断	if not User_JudgeLevelAndMetempsychosis(tRamadanActivity_Data["Level"],tRamadanActivity_Data["Metempsychosis"]) then		LinkNpcGossipFunc_New(nNpcId,"1-3")		return false	end		-- 失败，超过每日上交次数上限	 if nIndex ~= tRamadanActivity_Data["ItemId"]["Kinds"][15] then		local nEventType = tRamadanActivity_Data["Stc"][nIndex]["EventType"]		local nDataType = tRamadanActivity_Data["Stc"][nIndex]["DataType"]		local nComplete = tRamadanActivity_Data["Stc"][nIndex]["Complete"]		Task_StcReset(nEventType,nDataType) -- 隔天		if Task_ChkStcValue(nEventType,nDataType,">=",nComplete) then			LinkNpcGossipFunc_New(nNpcId,"3-4")			return false		end	end		-- 判断树是否满级	local nGlobalId = tRamadanActivity_Data["Global"]["Nutrient"]	local nNutrientLevel = Get_SysDynaGlobalData0(nGlobalId)	local nTopLevel = tRamadanActivity_Data["TopLevel"]		-- 满级	if nNutrientLevel >= nTopLevel then		-- RamadanActivity_NewSubmit(nNpcId,nIndex)		LinkNpcGossipFunc_New(nNpcId,"3-3")		return false	end		return trueend-- 上交宝物function RamadanActivity_Submit(nNpcId,nIndex)	-- 前置判断	if not RamadanActivity_BasicJudge(nNpcId,nIndex) then		return	end		-- 不满级	local nNutrient = tRamadanActivity_Data["SingleNutrient"][nIndex]	local nItemNum = tRamadanActivity_Data["ItemNum"]	tNpcGossip[nNpcId]["Text321"] = string.format(tRamadanActivity_Text[nNpcId]["Text321"],tRamadanActivity_Text["ItemName"][nIndex])		-- emoneylog	local sEmoneyLog = tRamadanActivity_Data["EmoneyLog"][nIndex]		-- 100天石（赠）	if nIndex == 1 then		local nNeedMonoEMoney = tRamadanActivity_Data["EMoneyMono"]		if Get_UserMonoEMoney() < nNeedMonoEMoney then			LinkNpcGossipFunc_New(nNpcId,"3-2")		else			User_AddEMoneyMono(-nNeedMonoEMoney)			RamadanActivity_AfterSubmit(nNpcId,nIndex,nNutrient,sEmoneyLog)		end		-- 祈福灵露	elseif nIndex == tRamadanActivity_Data["ItemId"]["Kinds"][15] then		nItemNum = Get_CountItemType(nIndex,0)		nNutrient = nItemNum * tRamadanActivity_Data["SingleNutrient"][nIndex]		if nItemNum <= 0 then			LinkNpcGossipFunc_New(nNpcId,"3-2")			return		end		if Item_ChkMulItem(nIndex,nIndex,nItemNum) and Item_DelMulItem(nIndex,nIndex,nItemNum) then			local sLog = string.format(tRamadanActivity_Data["Log"][nIndex],nItemNum)			Sys_SaveActionFestivalLog(sLog)			RamadanActivity_AfterSubmit(nNpcId,nIndex,nNutrient,sEmoneyLog)		else			LinkNpcGossipFunc_New(nNpcId,"3-2")		end		--被偷走的马鞍*30	elseif nIndex == tRamadanActivity_Data["ItemId"]["Kinds"][13] then		nItemNum = Get_CountItemType(nIndex,0)		nNutrient =  tRamadanActivity_Data["SingleNutrient"][nIndex]		if nItemNum <= 0 then			LinkNpcGossipFunc_New(nNpcId,"3-2")			return		end		if nItemNum<tRamadanActivity_Data["SaddleNum"] then			--马鞍不足30个			return		end		if Item_ChkMulItem(nIndex,nIndex,tRamadanActivity_Data["SaddleNum"]) and Item_DelMulItem(nIndex,nIndex,tRamadanActivity_Data["SaddleNum"]) then			RamadanActivity_AfterSubmit(nNpcId,nIndex,nNutrient,sEmoneyLog)		else			LinkNpcGossipFunc_New(nNpcId,"3-2")		end		-- 100000银两	elseif nIndex == 2 then		local nMoney = tRamadanActivity_Data["Money"]		if not User_CanPutMoney2Bag(-nMoney) then			LinkNpcGossipFunc_New(nNpcId,"3-2")		elseif User_AddMoney(-nMoney) then			RamadanActivity_AfterSubmit(nNpcId,nIndex,nNutrient,sEmoneyLog)		end--一封情书	elseif nIndex == tRamadanActivity_Data["ItemId"]["Kinds"][14] then 		local nMonopoly = tRamadanActivity_Data["Monopoly"]		local nItemNum = tRamadanActivity_Data["ItemNum"]		if Item_ChkMulItem(nIndex,nIndex,nItemNum,nMonopoly) and Item_DelMulItem(nIndex,nIndex,nItemNum,nMonopoly) then			RamadanActivity_AfterSubmit(nNpcId,nIndex,nNutrient,sEmoneyLog)		else			LinkNpcGossipFunc_New(nNpcId,"3-2")		end--红白恶之花	elseif nIndex == 6 then 		local nMonopoly = tRamadanActivity_Data["Monopoly"]		local nItemNum = tRamadanActivity_Data["EvilFlowerNum"]		local nItemIdRed=tRamadanActivity_Data["ItemId"]["EvilFlower"][1]		local nItemIdWhite=tRamadanActivity_Data["ItemId"]["EvilFlower"][2]		if Item_ChkMulItem(nItemIdRed,nItemIdRed,nItemNum,nMonopoly) and Item_DelMulItem(nItemIdRed,nItemIdRed,nItemNum,nMonopoly) 			and Item_ChkMulItem(nItemIdWhite,nItemIdWhite,nItemNum,nMonopoly) and Item_DelMulItem(nItemIdWhite,nItemIdWhite,nItemNum,nMonopoly) then			RamadanActivity_AfterSubmit(nNpcId,nIndex,nNutrient,sEmoneyLog)		else			LinkNpcGossipFunc_New(nNpcId,"3-2")		end		-- 流星卷	elseif nIndex == tRamadanActivity_Data["ItemId"]["Kinds"][12] then 		local nMonopoly = tRamadanActivity_Data["Monopoly"]		local nItemNum = tRamadanActivity_Data["ItemNum"]		if Item_ChkMulItem(nIndex,nIndex,nItemNum,nMonopoly) and Item_DelMulItem(nIndex,nIndex,nItemNum,nMonopoly) then			RamadanActivity_AfterSubmit(nNpcId,nIndex,nNutrient,sEmoneyLog)		else			LinkNpcGossipFunc_New(nNpcId,"3-2")		end	-- 龙珠（赠）	else		local nMonopoly = tRamadanActivity_Data["Monopoly1"]		local nItemNum = tRamadanActivity_Data["ItemNum"]		if Item_ChkMulItem(nIndex,nIndex,nItemNum,nMonopoly) and Item_DelMulItem(nIndex,nIndex,nItemNum,nMonopoly) then			RamadanActivity_AfterSubmit(nNpcId,nIndex,nNutrient,sEmoneyLog)		else			LinkNpcGossipFunc_New(nNpcId,"3-2")		end	endend-- 上交宝石function RamadanActivity_SubmitGems(nNpcId,nIndex)	local nTypeIndex = 3		-- 前置判断	if not RamadanActivity_BasicJudge(nNpcId,nTypeIndex) then		return	end		-- 不满级	local nNutrient = tRamadanActivity_Data["SingleNutrient"][nTypeIndex]	tNpcGossip[nNpcId]["Text321"] = string.format(tRamadanActivity_Text[nNpcId]["Text321"],tRamadanActivity_Text["ItemName"][nTypeIndex])	local sEmoneyLog = tRamadanActivity_Data["EmoneyLog"][nTypeIndex]		local nMonopoly = tRamadanActivity_Data["Monopoly"]	-- 同种宝石	if nIndex < 8 then		local nItemId = tRamadanActivity_Data["ItemId"]["Gem"][nIndex]		local nItemNum = tRamadanActivity_Data["GemNum"]		-- 上交成功		if Item_ChkMulItem(nItemId,nItemId,nItemNum,nMonopoly) and Item_DelMulItem(nItemId,nItemId,nItemNum,nMonopoly) then			local sLog = string.format(tRamadanActivity_Data["Log"]["Gem"],nItemId,nItemNum)			Sys_SaveActionFestivalLog(sLog)			RamadanActivity_AfterSubmit(nNpcId,nTypeIndex,nNutrient,sEmoneyLog)		-- 上交失败		else			LinkNpcGossipFunc_New(nNpcId,"3-2")		end	-- 异种宝石	else		-- 上交失败		if not RamadanActivity_HaveGems() then			LinkNpcGossipFunc_New(nNpcId,"3-2")			return		end		local tRandomGems = RamadanActivity_RandomGems()		for i = 1,#tRandomGems do			local nItemId = tRandomGems[i][1]			local nItemNum = tRandomGems[i][2]			if not Item_ChkMulItem(nItemId,nItemId,nItemNum,nMonopoly) then				LinkNpcGossipFunc_New(nNpcId,"3-2")				return			end		end		-- 上交成功		local sItemId = ""		local sItemNum = ""		local sLeft = "["		local sRight = "]"		for i = 1,#tRandomGems do			local nItemId = tRandomGems[i][1]			local nItemNum = tRandomGems[i][2]			Item_DelMulItem(nItemId,nItemId,nItemNum,nMonopoly)			-- log 处理			if i == 1 then				sItemId = tostring(nItemId)				sItemNum = tostring(nItemNum)			else				sItemId = sItemId .. sLeft .. tostring(nItemId) .. sRight				sItemNum = sItemNum .. sLeft .. tostring(nItemNum) .. sRight			end		end		sLog = string.format(tRamadanActivity_Data["Log"]["RandomGem"],sItemId,sItemNum)		Sys_SaveActionFestivalLog(sLog)		RamadanActivity_AfterSubmit(nNpcId,nTypeIndex,nNutrient,sEmoneyLog)	endend-- 上交鲜花function RamadanActivity_SubmitFlowers(nFlowerIndex,nNumIndex,nNpcId)	local nTypeIndex = 4		-- 前置判断	if not RamadanActivity_BasicJudge(nNpcId,nTypeIndex) then		return	end		-- 不满级	local nNutrient = tRamadanActivity_Data["SingleNutrient"]["Flower"][nNumIndex] -- 养分	local sEmoneyLog = tRamadanActivity_Data["EmoneyLog"]["Flower"][nNumIndex] -- emoneylog	tNpcGossip[nNpcId]["Text321"] = string.format(tRamadanActivity_Text[nNpcId]["Text321"],tRamadanActivity_Text["ItemName"][nTypeIndex])		local nMonopoly = tRamadanActivity_Data["Monopoly"]	local nItemId = tRamadanActivity_Data["ItemId"]["Flowers"][(nNumIndex-1)*4+nFlowerIndex]	local nItemNum = tRamadanActivity_Data["ItemNum"]	if nNumIndex == 1 then		nItemNum = tRamadanActivity_Data["FlowerNum"]	end	-- 上交成功	if Item_ChkMulItem(nItemId,nItemId,nItemNum,nMonopoly) and Item_DelMulItem(nItemId,nItemId,nItemNum,nMonopoly) then		RamadanActivity_AfterSubmit(nNpcId,nTypeIndex,nNutrient,sEmoneyLog)	-- 上交失败	else		LinkNpcGossipFunc_New(nNpcId,"3-2")	endend-- 成功上交后续操作function RamadanActivity_AfterSubmit(nNpcId,nIndex,nNutrient,sEmoneyLog)	-- emoneylog	Sys_SaveEmoneyBuy(sEmoneyLog)		-- stc(159,76) 记录每日上交物资次数 祈福灵露不算次数	 if nIndex ~= tRamadanActivity_Data["ItemId"]["Kinds"][15] then		local nSubmitEventType = tRamadanActivity_Data["Stc"][nIndex]["EventType"]		local nSubmitDataType = tRamadanActivity_Data["Stc"][nIndex]["DataType"]		Task_StcReset(nSubmitEventType,nSubmitDataType) -- 隔天		Task_AddStatistic(nSubmitEventType,nSubmitDataType,1,1)	end		-- stc(159,77) 记录每日贡献养分值	local nNutrientEventType = tRamadanActivity_Data["Stc"]["Nutrient"]["EventType"]	local nNutrientDataType = tRamadanActivity_Data["Stc"]["Nutrient"]["DataType"]	Task_StcReset(nNutrientEventType,nNutrientDataType) -- 隔天	Task_AddStatistic(nNutrientEventType,nNutrientDataType,nNutrient,1)		-- 记录玩家贡献阶段掩码	local nGlobalId = tRamadanActivity_Data["Global"]["Nutrient"]	local nNutrientLevel = Get_SysDynaGlobalData0(nGlobalId)	local nUserEventType = tRamadanActivity_Data["Stc"]["Contribution"]["EventType"]	local nUserDataType = tRamadanActivity_Data["Stc"]["Contribution"]["DataType"]	local nUserValue = Get_UserStatisticValue(nUserEventType,nUserDataType)	if not Sys_ParseNumbersContain(tRamadanActivity_Binary[nNutrientLevel+1],nUserValue) then		Task_AddStatistic(nUserEventType,nUserDataType,tRamadanActivity_Binary[nNutrientLevel+1],1)	end		-- 更新树状态	local nTreeNutrient = Get_SysDynaGlobalData1(nGlobalId) + nNutrient	-- 未升级	if nTreeNutrient < tRamadanActivity_Data["NeedNutrient"][nNutrientLevel+1] then		Sys_SetSynaGlobalData1(nGlobalId,nTreeNutrient)	-- 升级	else		local sNewLevel = nNutrientLevel+1		local sNewLevelName = tRamadanActivity_Text["LevelName"][sNewLevel]		local nTopLevel = tRamadanActivity_Data["TopLevel"]		if sNewLevel == nTopLevel then			nTreeNutrient = tRamadanActivity_Data["NeedNutrient"][nTopLevel]		else			nTreeNutrient = nTreeNutrient - tRamadanActivity_Data["NeedNutrient"][sNewLevel]		end		Sys_SetSynaGlobalData1(nGlobalId,nTreeNutrient)		Sys_SetSynaGlobalData0(nGlobalId,sNewLevel)		Sys_SystemBroadcast(string.format(tRamadanActivity_Text["Broadcast"]["Grow"],sNewLevel))		-- 判断外形是否变大		for i,v in pairs(tRamadanActivity_Data["TreeNpcId"]) do			if i == sNewLevel then				local nShowNpcId = v				local nShowMapId = tRamadanActivity_Data["Show"]["MapId"]				local nShowPosX = tRamadanActivity_Data["Show"]["PosX"]				local nShownPosY = tRamadanActivity_Data["Show"]["PosY"]				local nHideNpcId = nNpcId				local nHideMapId = tRamadanActivity_Data["Hide"]["MapId"]				local nHidePosX = tRamadanActivity_Data["Hide"]["PosX"]				local nHidePosY =tRamadanActivity_Data["Hide"]["PosY"]				Npc_MoveNpcPos(nShowNpcId,nShowMapId,nShowPosX,nShownPosY)				Npc_MoveNpcPos(nHideNpcId,nHideMapId,nHidePosX,nHidePosY)				Sys_SystemBroadcast(string.format(tRamadanActivity_Text["Broadcast"]["Change"],sNewLevelName))				break			end		end	end			-- 对白 光效	tNpcGossip[nNpcId]["Text311"] = string.format(tRamadanActivity_Text[nNpcId]["Text311"],tRamadanActivity_Text["ItemName"][nIndex],nNutrient)	local nNextLevel = Get_SysDynaGlobalData0(nGlobalId)+1	if nNextLevel >= tRamadanActivity_Data["TopLevel"] then		tNpcGossip[nNpcId]["Text312"] = string.format(tRamadanActivity_Text[nNpcId]["Text312"],tRamadanActivity_Text["None"])		tNpcGossip[nNpcId]["Text313"] = string.format(tRamadanActivity_Text[nNpcId]["Text313"],tRamadanActivity_Text["None"])	else		tNpcGossip[nNpcId]["Text312"] = string.format(tRamadanActivity_Text[nNpcId]["Text312"],tRamadanActivity_Text["LevelName"][nNextLevel])		tNpcGossip[nNpcId]["Text313"] = string.format(tRamadanActivity_Text[nNpcId]["Text313"],tRamadanActivity_Text["LevelReward"][nNextLevel])	end	LinkNpcGossipFunc_New(nNpcId,"3-1")	User_EffectAdd("self",tRamadanActivity_Data["Effect"]["SubmitReward"])		-- 排行榜	local nLeastScore = tRamadanActivity_Data["LeastScore"]	-- 不到上排行榜下限不进行排名	if Task_ChkStcValue(nNutrientEventType,nNutrientDataType,"<",nLeastScore) then		return	end	-- 不大于排行榜最后一名不进行排名	local nRankGlobalId = tRamadanActivity_Data["Global"][2][1]	local nRankTen = Get_SysDynaGlobalData5(nRankGlobalId)	if Task_ChkStcValue(nNutrientEventType,nNutrientDataType,"<=",nRankTen) then		return	end		-- 进行排名	local nNowNutrient = Get_UserStatisticValue(nNutrientEventType,nNutrientDataType)	RamadanActivity_Rank(nNowNutrient)end-- 是否有任意5颗普通宝石function RamadanActivity_HaveGems()	local nItemNum = 0	local nMonopoly = tRamadanActivity_Data["Monopoly"]	for i,v in pairs (tRamadanActivity_Data["ItemId"]["Gem"]) do		nItemNum = nItemNum + Get_CountItemType(v,0,nMonopoly)	end	return nItemNum >= 5end-- 任意5颗普通宝石function RamadanActivity_RandomGems()	local nSubmitNum = tRamadanActivity_Data["GemNum"]	local nTotalNum = 0	local nMonopoly = tRamadanActivity_Data["Monopoly"]	local nIndex = 1	local nFlag = 1	local tRandomGems = {}	local nCalLoop = 0	while nTotalNum < nSubmitNum do		if nCalLoop > G_CalculateLoop then			Sys_SaveAbnormalLog("函数 RamadanActivity_RandomGems 中 [while]循环超过1000次！")			break		end		nCalLoop = nCalLoop + 1		local nItemId = tRamadanActivity_Data["ItemId"]["Gem"][nFlag]		local nItemNum = Get_CountItemType(nItemId,0,nMonopoly)		if nItemNum > 0 then			if nItemNum + nTotalNum >= nSubmitNum then				tRandomGems[nIndex] = {nItemId,nSubmitNum-nTotalNum}				nTotalNum = nSubmitNum				break			else				tRandomGems[nIndex] = {nItemId,nItemNum}				nTotalNum = nTotalNum + nItemNum			end			nIndex = nIndex + 1		end		nFlag = nFlag + 1		if nFlag > 7 then			break		end	end	return tRandomGemsend-- 是否有满足上交要求的鲜花function RamadanActivity_HaveFlowers(tFlower,nFlag)	local nMonopoly = tRamadanActivity_Data["Monopoly"]	local nNeedNum = 0	for i,v in pairs (tFlower) do		if #tFlower > 5 then			-- 单朵			if i <= nFlag then				nNeedNum = tRamadanActivity_Data["FlowerNum"]			-- 非单朵			else				nNeedNum = tRamadanActivity_Data["ItemNum"]			end		else			-- 单朵			if i == 1 then				nNeedNum = tRamadanActivity_Data["FlowerNum"]			-- 非单朵			else				nNeedNum = tRamadanActivity_Data["ItemNum"]			end		end		local nItemId = tFlower[i]		local nItemNum = Get_CountItemType(nItemId,0)		if nItemNum > 0 then			if Item_ChkMulItem(nItemId,nItemId,nNeedNum,nMonopoly) then				return true			end		end	end	return falseend-- 鲜花选项判断function RamadanActivity_FlowersOption(nFlowerIndex,nNumIndex)	local nMonopoly = tRamadanActivity_Data["Monopoly"]	local nItemId = tRamadanActivity_Data["ItemId"]["Flowers"][(nNumIndex-1)*4+nFlowerIndex]	local nItemNum = Get_CountItemType(nItemId,0)	local nNeedItem = tRamadanActivity_Data["ItemNum"]	if nNumIndex == 1 then		nNeedItem = tRamadanActivity_Data["FlowerNum"]	end	if nItemNum <= 0 then		return false	end	return Item_ChkMulItem(nItemId,nItemId,nNeedItem)end-- 上交宝物 树满级，新玩法--[[function RamadanActivity_NewSubmit(nNpcId,nIndex)	local nNutrient = tRamadanActivity_Data["SingleNutrient"][nIndex]	local nItemNum = tRamadanActivity_Data["ItemNum"]	tNpcGossip[nNpcId]["Text321"] = string.format(tRamadanActivity_Text[nNpcId]["Text321"],tRamadanActivity_Text["ItemName"][nIndex])		-- log	local sLog = ""	if tRamadanActivity_Data["EmoneyLog"][nIndex] ~= "" then		sLog = tRamadanActivity_Data["EmoneyLog"][nIndex]	else		nItemNum = Get_CountItemType(nIndex,0)		sLog = string.format(tRamadanActivity_Data["Log"][nIndex],nItemNum)	end		-- 10天石（赠）	if nIndex == 1 then		local nNeedMonoEMoney = tRamadanActivity_Data["EMoneyMono"]		if Get_UserMonoEMoney() < nNeedMonoEMoney then			LinkNpcGossipFunc_New(nNpcId,"3-2")		else			User_AddEMoneyMono(-nNeedMonoEMoney)			RamadanActivity_NewAfterSubmit(nNpcId,nIndex,nNutrient,sLog)		end		-- 祈福灵露	elseif nIndex == tRamadanActivity_Data["ItemId"]["Kinds"][13] then		nItemNum = Get_CountItemType(nIndex,0)		nNutrient = nItemNum * tRamadanActivity_Data["SingleNutrient"][nIndex]		if Item_ChkMulItem(nIndex,nIndex,nItemNum) and Item_DelMulItem(nIndex,nIndex,nItemNum) then			RamadanActivity_NewAfterSubmit(nNpcId,nIndex,nNutrient,sLog)		else			LinkNpcGossipFunc_New(nNpcId,"3-2")		end		-- 30000银两	elseif nIndex == 2 then		local nMoney = tRamadanActivity_Data["Money"]		local nMoneyOption = tRamadanActivity_Data["MoneyOption"]		if not User_CanPutMoney2Bag(-nMoney) then			LinkNpcGossipFunc_New(nNpcId,"3-2")		elseif User_AddMoney(-nMoney) then			RamadanActivity_NewAfterSubmit(nNpcId,nIndex,nNutrient,sLog)		end		-- 其他宝物	else		local nMonopoly = tRamadanActivity_Data["Monopoly"]		local nItemNum = tRamadanActivity_Data["ItemNum"]		if Item_ChkMulItem(nIndex,nIndex,nItemNum,nMonopoly) and Item_DelMulItem(nIndex,nIndex,nItemNum,nMonopoly) then			RamadanActivity_NewAfterSubmit(nNpcId,nIndex,nNutrient,sLog)		else			LinkNpcGossipFunc_New(nNpcId,"3-2")		end	endend--]]-- 成功上交后续操作 树满级，新玩法--[[function RamadanActivity_NewAfterSubmit(nNpcId,nIndex,nNutrient,sLog)	-- 打log	Sys_SaveActionFestivalLog(sLog)		-- stc(159,76) 记录每日上交物资次数	local nSubmitEventType = tRamadanActivity_Data["Stc"]["Submit"]["EventType"]	local nSubmitDataType = tRamadanActivity_Data["Stc"]["Submit"]["DataType"]	if Task_StcInterval(nSubmitEventType,nSubmitDataType,1,4) then		Task_SetStatistic(nSubmitEventType,nSubmitDataType,0,1)		Task_SetStcTimestamp(nSubmitEventType,nSubmitDataType,0)	end	Task_AddStatistic(nSubmitEventType,nSubmitDataType,1,1)		-- stc(159,77) 记录每日贡献养分值	local nNutrientEventType = tRamadanActivity_Data["Stc"]["Nutrient"]["EventType"]	local nNutrientDataType = tRamadanActivity_Data["Stc"]["Nutrient"]["DataType"]	if Task_StcInterval(nNutrientEventType,nNutrientDataType,1,4) then		Task_SetStatistic(nNutrientEventType,nNutrientDataType,0,1)		Task_SetStcTimestamp(nNutrientEventType,nNutrientDataType,0)	end	Task_AddStatistic(nNutrientEventType,nNutrientDataType,nNutrient,1)		-- stc(161,81) 记录玩家培育进度值	local nNewEventType = tRamadanActivity_Data["Stc"]["New"]["EventType"]	local nNewDataType = tRamadanActivity_Data["Stc"]["New"]["DataType"]	Task_AddStatistic(nNewEventType,nNewDataType,nNutrient,1)		-- 对白 光效	tNpcGossip[nNpcId]["Text381"] = string.format(tRamadanActivity_Text[nNpcId]["Text381"],tRamadanActivity_Text["ItemName"][nIndex],nNutrient)	LinkNpcGossipFunc_New(nNpcId,"3-8")	User_EffectAdd("self",tRamadanActivity_Data["Effect"]["SubmitReward"])		-- 排行榜	local nLeastScore = tRamadanActivity_Data["LeastScore"]	-- 不到上排行榜下限不进行排名	if Task_ChkStcValue(nNutrientEventType,nNutrientDataType,"<",nLeastScore) then		return	end	-- 不大于排行榜最后一名不进行排名	local nRankGlobalId = tRamadanActivity_Data["Global"][2][1]	local nRankTen = Get_SysDynaGlobalData5(nRankGlobalId)	if Task_ChkStcValue(nNutrientEventType,nNutrientDataType,"<=",nRankTen) then		return	end		-- 进行排名	local nNowNutrient = Get_UserStatisticValue(nNutrientEventType,nNutrientDataType)	RamadanActivity_Rank(nNowNutrient)end-]]-- 排行榜排序function RamadanActivity_Rank(nNowScore)	local tRankUserData = {}	-- 获得排行榜玩家信息	local nIndex = 0	-- for j = 1,2 do		-- for i = 1,5 do		for i = 1,3 do			-- local nGlobalId = tRamadanActivity_Data["Global"][j][1]			local nGlobalId = tRamadanActivity_Data["Global"][1][1]			local nScore = Get_SysDynaGlobalData(nGlobalId,i)			local sUsername = Get_SysDynaGlobalDataStr(nGlobalId,i)			nIndex = nIndex + 1			tRankUserData[nIndex] = {}			tRankUserData[nIndex]["Score"] = nScore == "" and 0 or nScore			tRankUserData[nIndex]["Username"] = sUsername == "" and "null" or sUsername		end	-- end		nIndex = 0	-- for j = 1,2 do		-- for i = 1,5 do		for i = 1,3 do			-- local nGlobalId = tRamadanActivity_Data["Global"][j][2]			local nGlobalId = tRamadanActivity_Data["Global"][1][2]			local nUserId = Get_SysDynaGlobalData(nGlobalId,i)			nIndex = nIndex + 1			tRankUserData[nIndex]["UserId"] = nUserId		end	-- end		-- 将玩家加入到临时排行表中	nIndex = #tRankUserData + 1	local nNowUserId = Get_UserId()	-- for i = 1,10 do	for i = 1,3 do		if nNowUserId == tRankUserData[i]["UserId"] then			nIndex = i		end	end	tRankUserData[nIndex] = {}	tRankUserData[nIndex]["Score"] = nNowScore	tRankUserData[nIndex]["UserId"] = nNowUserId	tRankUserData[nIndex]["Username"] = Get_UserName(nNowUserId)		-- 对临时排行榜表进行排序	local t = {}	for i = 1, #tRankUserData do		for j = 1, #tRankUserData - i do			if tRankUserData[j]["UserId"] == 0 or (tRankUserData[j]["Score"] < tRankUserData[j+1]["Score"] and tRankUserData[j+1]["UserId"] ~= 0) then				t = tRankUserData[j]				tRankUserData[j] = tRankUserData[j+1]				tRankUserData[j+1] = t			end		end	end		-- 将排序完的数据更新到全局表中	-- for i = 1,10 do	for i = 1,3 do		local nScore = tRankUserData[i]["Score"]		local nUserId = tRankUserData[i]["UserId"]		local sUsername = tRankUserData[i]["Username"]				if nScore == 0 then			nUserId = 0			sUsername = ""		end				if i > 5 then			Sys_SetSynaGlobalData(tRamadanActivity_Data["Global"][2][1],i-5,nScore)			Sys_SetSynaGlobalDataStr(tRamadanActivity_Data["Global"][2][1],i-5,sUsername)			Sys_SetSynaGlobalData(tRamadanActivity_Data["Global"][2][2],i-5,nUserId)		else			Sys_SetSynaGlobalData(tRamadanActivity_Data["Global"][1][1],i,nScore)			Sys_SetSynaGlobalDataStr(tRamadanActivity_Data["Global"][1][1],i,sUsername)			Sys_SetSynaGlobalData(tRamadanActivity_Data["Global"][1][2],i,nUserId)		end	endend-- 领取奖励function RamadanActivity_Award(nNpcId)	-- 失败，活动已经结束	if not Sys_ChkFullTime(tActivityTime["RamadanActivity"]["ActivityTime"]) then		LinkNpcGossipFunc_New(nNpcId,"1-2")		return	end		-- 失败，等级判断	if not User_JudgeLevelAndMetempsychosis(tRamadanActivity_Data["Level"],tRamadanActivity_Data["Metempsychosis"]) then		LinkNpcGossipFunc_New(nNpcId,"1-3")		return	end		-- 失败，没有可领奖次数	local nTimes = RamadanActivity_CanRewardTimes()	if nTimes == 0 then		return	end		-- 失败，背包空间不足	local nSpace = nTimes	if not User_CheckLeftSpace(nSpace) then		tNpcGossip[nNpcId]["Text231"] = string.format(tRamadanActivity_Text[nNpcId]["Text231"],nSpace)		LinkNpcGossipFunc_New(nNpcId,"2-3")		return	end		-- 成功	local nGlobalId = tRamadanActivity_Data["Global"]["Nutrient"]	local nNutrientLevel = Get_SysDynaGlobalData0(nGlobalId)	for i = 1,nNutrientLevel do		local nAwardEventType = tRamadanActivity_Data["Stc"]["Award"]["EventType"]		local nAwardDataType = tRamadanActivity_Data["Stc"]["Award"]["DataType"]		local nAwardValue = Get_UserStatisticValue(nAwardEventType,nAwardDataType)		if not Sys_ParseNumbersContain(tRamadanActivity_Binary[i],nAwardValue) then			local sMsg = ""			local nLevelName = tRamadanActivity_Text["LevelName"][i]			local sLevelReward = tRamadanActivity_Text["LevelAward"][i]			local nContributionEventType = tRamadanActivity_Data["Stc"]["Contribution"]["EventType"]			local nContributionDataType = tRamadanActivity_Data["Stc"]["Contribution"]["DataType"]			local nContributionValue = Get_UserStatisticValue(nContributionEventType,nContributionDataType)			-- 领取有贡献的奖励			if Sys_ParseNumbersContain(tRamadanActivity_Binary[i],nContributionValue) then				Task_AddStatistic(nAwardEventType,nAwardDataType,tRamadanActivity_Binary[i],1)				RewardTemplate_UseItemAndMsg(tRamadanActivity_Reward["Contribution"][i])				sMsg = string.format(tRamadanActivity_Text["RewardMsg"]["Yes"],nLevelName,sLevelReward)				User_TalkChannel2005(sMsg)				Sys_SaveEmoneyBuy(tRamadanActivity_Data["EmoneyLog"]["Contribution"][i])			-- 领取无贡献的奖励			-- else				-- Task_AddStatistic(nAwardEventType,nAwardDataType,tRamadanActivity_Binary[i],1)				-- RewardTemplate_UseItemAndMsg(tRamadanActivity_Reward["NoContribution"])				-- sMsg = string.format(tRamadanActivity_Text["RewardMsg"]["No"],nLevelName)				-- User_TalkChannel2005(sMsg)			end		end	endend-- 判断可领奖次数-- function RamadanActivity_CanRewardTimes()	-- local nGlobalId = tRamadanActivity_Data["Global"]["Nutrient"]	-- local nNutrientLevel = Get_SysDynaGlobalData0(nGlobalId)	-- local nEventType = tRamadanActivity_Data["Stc"]["Award"]["EventType"]	-- local nDataType = tRamadanActivity_Data["Stc"]["Award"]["DataType"]	-- local nValue = Get_UserStatisticValue(nEventType,nDataType)	-- local nTimes = 0		-- if nNutrientLevel ~= 0 then		-- for i = 1,nNutrientLevel do			-- if not Sys_ParseNumbersContain(tRamadanActivity_Binary[i],nValue) then				-- nTimes = nTimes + 1			-- end		-- end	-- end	-- return nTimes-- endfunction RamadanActivity_CanRewardTimes()	local nGlobalId = tRamadanActivity_Data["Global"]["Nutrient"]	local nNutrientLevel = Get_SysDynaGlobalData0(nGlobalId)	local nEventType = tRamadanActivity_Data["Stc"]["Award"]["EventType"]	local nDataType = tRamadanActivity_Data["Stc"]["Award"]["DataType"]	local nEventType1 = tRamadanActivity_Data["Stc"]["Contribution"]["EventType"]	local nDataType1 = tRamadanActivity_Data["Stc"]["Contribution"]["DataType"]	local nValue = Get_UserStatisticValue(nEventType,nDataType)	local nValue1 = Get_UserStatisticValue(nEventType1,nDataType1)	local nTimes = 0		if nNutrientLevel ~= 0 then		if Task_ChkStcValue(nEventType1,nDataType1,">",0) then			for i = 1,nNutrientLevel do				if (Sys_ParseNumbersContain(tRamadanActivity_Binary[i],nValue1)) and (not Sys_ParseNumbersContain(tRamadanActivity_Binary[i],nValue)) then					nTimes = nTimes + 1				end			end		end	end	return nTimesend-- 培育进度换礼包 树满级，新玩法--[[function RamadanActivity_NewAward(nNpcId,nIndex)	-- 失败，活动已经结束	if not Sys_ChkFullTime(tActivityTime["RamadanActivity"]["ActivityTime"]) then		LinkNpcGossipFunc_New(nNpcId,"1-2")		return	end		-- 失败，等级判断	if not User_JudgeLevelAndMetempsychosis(tRamadanActivity_Data["Level"],tRamadanActivity_Data["Metempsychosis"]) then		return	end		-- 失败，培育进度不足	local nNewEventType = tRamadanActivity_Data["Stc"]["New"]["EventType"]	local nNewDataType = tRamadanActivity_Data["Stc"]["New"]["DataType"]	if Task_ChkStcValue(nNewEventType,nNewDataType,"<",nIndex) then		tNpcGossip[nNpcId]["Text411"] = string.format(tRamadanActivity_Text[nNpcId]["Text411"],nIndex,tRamadanActivity_Text["NewPack"][nIndex])		LinkNpcGossipFunc_New(nNpcId,"4-1")		return	end		-- 失败，背包空间不足	local nSpace = tRamadanActivity_Data["OneSpace"]	if not User_CheckLeftSpace(nSpace) then		LinkNpcGossipFunc_New(nNpcId,"4-2")		return	end		-- 失败，判断掩码	local nPackEventType = tRamadanActivity_Reward[nIndex]["EventType"]	local nPackDataType = tRamadanActivity_Reward[nIndex]["DataType"]	local nPackLimit = tRamadanActivity_Reward[nIndex]["RewardTotalData"]	local nData = Get_UserStatisticValue(nPackEventType,nPackDataType)/10000	local sLimit = string.format(tRamadanActivity_Text["Limit"],tRamadanActivity_Text["NewPack"][nIndex])	if nData >= nPackLimit then		Sys_MsgBox(sLimit)		return	end		-- 成功 打掩码 给奖励 出提示及对白	local sMsg = string.format(tRamadanActivity_Text["AwardNewPack"],nIndex,tRamadanActivity_Text["NewPack"][nIndex])	Task_AddStatistic(nNewEventType,nNewDataType,-nIndex,1)	if RewardTemplate_UseItemAndMsg(tRamadanActivity_Reward[nIndex]) then		User_TalkChannel2005(sMsg)	end	LinkNpcGossipFunc_New(nNpcId,"2-9")end--]]-- 进度条function RamadanActivity_ProgressBar()	local nGlobalId = tRamadanActivity_Data["Global"]["Nutrient"]	local nNutrientLevel = Get_SysDynaGlobalData0(nGlobalId)	local nNutrient = Get_SysDynaGlobalData1(nGlobalId)	local nTopLevel = tRamadanActivity_Data["TopLevel"]		-- 区分满级与非满级	local nNeedNutrient = 0	if nNutrientLevel >= nTopLevel then		nNeedNutrient = tRamadanActivity_Data["NeedNutrient"][nNutrientLevel]	else		nNeedNutrient = tRamadanActivity_Data["NeedNutrient"][nNutrientLevel+1]	end		-- 40格时的每格养分值 以及 当前格数	local nUnitNutrient = nNeedNutrient / 40	local nBlack = math.floor(nNutrient/nUnitNutrient)		-- 进度条	local sBlack = tRamadanActivity_Text["Symbol"]["Black"]	local sEnd = tRamadanActivity_Text["Symbol"]["End"]	local sAll = "	"	if nBlack > 0 then		for i = 1, nBlack do			sAll = sAll .. sBlack		end	else		sAll = sAll .. sBlack	end		return sAllend-- 使用正气令function RamadanActivity_ChiToken()	-- 活动时间判断	if not Sys_ChkFullTime(tActivityTime["RamadanActivity"]["ActivityTime"]) then		return	end		local nEventType = tRamadanActivity_Data["Stc"]["ChiToken"]["EventType"]	local nDataType = tRamadanActivity_Data["Stc"]["ChiToken"]["DataType"]	local nComplete = tRamadanActivity_Data["Stc"]["ChiToken"]["Complete"]	-- 隔天	if Task_StcInterval(nEventType,nDataType,1,4) then		Task_SetStatistic(nEventType,nDataType,0,1)		Task_SetStcTimestamp(nEventType,nDataType,0)	end	if Task_ChkStcValue(nEventType,nDataType,">=",nComplete) then		return	end		Task_SetStatistic(nEventType,nDataType,1,1)	Task_SetStcTimestamp(nEventType,nDataType,0)	RewardTemplate_UseItemAndMsg(tRamadanActivity_Reward["ChiToken"])end-- 打开竞技场礼包function RamadanActivity_ArenaPack()	-- 活动时间判断	if not Sys_ChkFullTime(tActivityTime["RamadanActivity"]["ActivityTime"]) then		return	end		local nEventType = tRamadanActivity_Data["Stc"]["ArenaPack"]["EventType"]	local nDataType = tRamadanActivity_Data["Stc"]["ArenaPack"]["DataType"]	local nComplete = tRamadanActivity_Data["Stc"]["ArenaPack"]["Complete"]	-- 隔天	if Task_StcInterval(nEventType,nDataType,1,4) then		Task_SetStatistic(nEventType,nDataType,0,1)		Task_SetStcTimestamp(nEventType,nDataType,0)	end	if Task_ChkStcValue(nEventType,nDataType,">=",nComplete) then		return	end		Task_AddStatistic(nEventType,nDataType,1,1)	Task_SetStcTimestamp(nEventType,nDataType,0)	RewardTemplate_UseItemAndMsg(tRamadanActivity_Reward["ArenaPack"])end--------------------------------------时间自检逻辑--------------------------------------------- 第二日凌晨，将昨日前十玩家ID存入相应动态码，清空记录今日前十玩家信息的动态码function RamadanActivity_RankInfo()	-- 取数据	local tRankUserData = {}	local nIndex = 0	-- for j = 1,2 do		-- for i = 1,5 do		for i = 1,3 do			local nGlobalId = tRamadanActivity_Data["Global"][1][2]			local nUserId = Get_SysDynaGlobalData(nGlobalId,i)			nIndex = nIndex + 1			tRankUserData[nIndex] = nUserId		end	-- end		-- 转存	-- for i = 1,10 do	for i = 1,3 do		local nUserId = tRankUserData[i]		if i > 5 then			Sys_SetSynaGlobalData(tRamadanActivity_Data["Global"][3][2],i-5,nUserId)		else			Sys_SetSynaGlobalData(tRamadanActivity_Data["Global"][3][1],i,nUserId)		end	end		-- 清数据	-- for j = 1,2 do		for i = 1,2 do			-- Sys_ResetAllSynaGlobalData(tRamadanActivity_Data["Global"][j][i])			Sys_ResetAllSynaGlobalData(tRamadanActivity_Data["Global"][1][i])			-- Sys_ResetAllSynaGlobalDataStr(tRamadanActivity_Data["Global"][j][i])			Sys_ResetAllSynaGlobalDataStr(tRamadanActivity_Data["Global"][1][i])		end	-- endend-- 邮件发奖function RamadanActivity_SendMail()	-- 活动时间判断	if not Sys_ChkFullTime(tActivityTime["RamadanActivity"]["MailTime"]) then		return	end		-- 判断是否发奖	local nGlobalId = tRamadanActivity_Data["Global"]["Nutrient"]	local nData3 = Get_SysDynaGlobalData3(nGlobalId)	if nData3 ~= 0 then		return	end		-- 发奖：置开关，取数据，发邮件，打emoneylog	Sys_SetSynaGlobalData3(nGlobalId,1)	local tRankUserData = {}	local nIndex = 0	-- for j = 1,2 do		for i = 1,5 do			-- local nRankGlobalId = tRamadanActivity_Data["Global"][3][j]			local nRankGlobalId = tRamadanActivity_Data["Global"][3][1]			local nUserId = Get_SysDynaGlobalData(nRankGlobalId,i)			nIndex = nIndex + 1			tRankUserData[nIndex] = nUserId		end	-- end		local tUserRankReward = CommonFunc_Copy(tRankUserData)	for k,v in ipairs(tUserRankReward) do		if v ~= nil and v ~= 0 then			local sSender = tRamadanActivity_Text["SendMail"]["Sender"]			local sTitle = tRamadanActivity_Text["SendMail"]["Title"]			local sContent = string.format(tRamadanActivity_Text["SendMail"]["Content"],k)			local nExistDay = tRamadanActivity_Data["SendMail"]["ExistDay"]			local nActionId = 0			-- local sEmoneyLog = ""			if k <= 3 then				nActionId = tRamadanActivity_Data["SendMail"][k]				-- sEmoneyLog = tRamadanActivity_Data["EmoneyLog"]["SendMail"][k]			else				nActionId = tRamadanActivity_Data["SendMail"][4]				-- sEmoneyLog = tRamadanActivity_Data["EmoneyLog"]["SendMail"][4]			end			Sys_SendMail(v,0,0,nActionId,0,nExistDay,sSender,sTitle,sContent)			-- Sys_SaveEmoneyBuy(sEmoneyLog,v)		end	end	end-- 自检限制清除function RamadanActivity_ResetLimit()	-- 判断活动时间	if not Sys_ChkFullTime(tActivityTime["RamadanActivity"]["MailTime"]) then		return	end		local nGlobalId = tRamadanActivity_Data["Global"]["Nutrient"]	Sys_SetSynaGlobalData3(nGlobalId,0)end--------------------------------------物品使用逻辑--------------------------------------------- 斋月礼花function RamadanActivity_UseFire(nItemId)	-- 判断时间	if not Sys_ChkFullTime(tActivityTime["RamadanActivity"]["ActivityTime"]) then		local nNum = Get_CountItemType(nItemId,0)		Item_DelMulItem(nItemId,nItemId,nNum)		User_TalkChannel2005(tRamadanActivity_Text[nItemId]["TimeOut"])		return	end		-- 判断CD	local nEventType = tRamadanActivity_Data["Stc"]["UseFirework"]["EventType"]	local nDataType = tRamadanActivity_Data["Stc"]["UseFirework"]["DataType"]	if not Task_StcInterval(nEventType,nDataType,10,0) then		User_TalkChannel2005(tRamadanActivity_Text[nItemId]["CD"])		return	end		if Item_DelItem(nItemId) then		Task_SetStatistic(nEventType,nDataType,1,1)		Task_SetStcTimestamp(nEventType,nDataType,0)		User_EffectAdd("self",tRamadanActivity_Data["Effect"]["Firework"])		Sys_SaveActionFestivalLog(tRamadanActivity_Data["Log"][nItemId])	end	end-- 祈福灵露function RamadanActivity_UseDew(nItemId)	-- 判断时间	if not Sys_ChkFullTime(tActivityTime["RamadanActivity"]["ActivityTime"]) then		local nNum = Get_CountItemType(nItemId,0)		Item_DelMulItem(nItemId,nItemId,nNum)		User_TalkChannel2005(tRamadanActivity_Text[nItemId]["TimeOut"])		return	end		-- 寻路	local nPosX = tRamadanActivity_Data["NPC"]["CellX"]	local nPosY = tRamadanActivity_Data["NPC"]["CellY"]	local nMapId = tRamadanActivity_Data["NPC"]["MapId"]	local nNpcId = tRamadanActivity_Data["NPC"]["NpcId"]	Sys_GotoSomeWhere(nPosX,nPosY,nMapId,nNpcId)end-- 祈福礼盒function RamadanActivity_UseBox(nItemId,nIndex)	if not Item_ChkItem(nItemId) then		Sys_MsgBox(tRamadanActivity_Text[nItemId]["NoItem"])		return	end		RewardTemplate_UseItemAndMsg(tRamadanActivity_Reward[nItemId][nIndex])end--幸运礼包使用function RamadanActivity_UseLuckyPack(nItemId)	if not Item_ChkItem(nItemId) then		return	end--背包空间判断	local nSpace = RewardTemplate_GetRandomSpace(tRamadanActivity_Reward["LuckyPacks"],nItemId)	if not User_CheckLeftSpace(nSpace) then		local sText=string.format(tRamadanActivity_Text["NoSpace"],nSpace)		User_TalkChannel2005(sText)		return 	end	if Item_ChkItem(nItemId) and Item_DelItem(nItemId) then			--记删除礼包log		local sLog = string.format(tRamadanActivity_Data["Log"][nItemId],1)		Sys_SaveActionFestivalLog(sLog)		--记获得代金券log		local tReward = RewardTemplate_NewRandom(tRamadanActivity_Reward["LuckyPacks"],nItemId) 		local nGiveItemId =tReward[1]["tAward"][1]["RewardItem"][1]["Id"]		if nGiveItemId==3311166 then			Sys_SaveEmoneyBuy(tRamadanActivity_Data["EmoneyLog"][nGiveItemId])		end 		if nGiveItemId==3311167 then			Sys_SaveEmoneyBuy(tRamadanActivity_Data["EmoneyLog"][nGiveItemId])		end 		if nGiveItemId==3311168 then			Sys_SaveEmoneyBuy(tRamadanActivity_Data["EmoneyLog"][nGiveItemId])		end 		return	end end --------------------------------------npc模块---------------------------------------------------------------------------------- 20637 斋月祈福大使-- 头像tNpcFace[5429] = 15tNpcGossip[20637] = tNpcGossip[20637] or DefaultNpc:new{}tNpcGossip[20637]["OptionHidden"] = 1tNpcGossip[20637]["DialogueText"] = tRamadanActivity_Text[20637]-- 活动前tNpcGossip[20637]["Text1-1"] = {111,112,113,114,115