alse	end	-- 置掩码	Task_SetStatistic(nEventType,nDataType,nComplete,1)		return trueendtNpcGossip[i]["OptionChkFunc4"] = function()	-- Option4 Nourish~the~tree. 满级前显示	local nGlobalId = tRamadanActivity_Data["Global"]["Nutrient"]	local nNutrientLevel = Get_SysDynaGlobalData0(nGlobalId)	local nTopLevel = tRamadanActivity_Data["TopLevel"]	return nNutrientLevel < nTopLevelendtNpcGossip[i]["OptionChkFunc5"] = function()	-- Option5 Claim~my~reward. 有领奖次数显示	local nTimes = RamadanActivity_CanRewardTimes()	return nTimes ~= 0end-- 等级满足条件（非首次点击点击）tNpcGossip[i]["Text1-5"] = {151,152,153,154,155,156,157}tNpcGossip[i]["tOption1-5"] = {4,5,8,6,7}tNpcGossip[i]["ChkFunc1-5"] = function()	-- 判断活动时间	if not Sys_ChkFullTime(tActivityTime["RamadanActivity"]["ActivityTime"]) then		return false	end		-- 判断等级	if not User_JudgeLevelAndMetempsychosis(tRamadanActivity_Data["Level"],tRamadanActivity_Data["Metempsychosis"]) then		return false	end		-- 判断是否是首次点击	local nEventType = tRamadanActivity_Data["Stc"]["First"]["EventType"]	local nDataType = tRamadanActivity_Data["Stc"]["First"]["DataType"]	local nComplete = tRamadanActivity_Data["Stc"]["First"]["Complete"]	if Task_ChkStcValue(nEventType,nDataType,"<",nComplete) then		return false	end		-- 判断是否满级	local nGlobalId = tRamadanActivity_Data["Global"]["Nutrient"]	local nNutrientLevel = Get_SysDynaGlobalData0(nGlobalId)	local nNutrient = Get_SysDynaGlobalData1(nGlobalId)	local nTopLevel = tRamadanActivity_Data["TopLevel"]	if nNutrientLevel < nTopLevel then		tNpcGossip[i]["Text154"] = string.format(tRamadanActivity_Text[i]["Text154"],nNutrient,tRamadanActivity_Data["NeedNutrient"][nNutrientLevel+1])		tNpcGossip[i]["Text155"] = string.format(tRamadanActivity_Text[i]["Text155"],tRamadanActivity_Text["LevelName"][nNutrientLevel+1])		tNpcGossip[i]["Text157"] = string.format(tRamadanActivity_Text[i]["Text157"],tRamadanActivity_Text["LevelReward"][nNutrientLevel+1])	else		tNpcGossip[i]["Text154"] = string.for